import { TYPES } from '@src/di/types/types';
import type { IWeatherRepository } from '@src/domain/interfaces/weather';
import { Query } from '@src/domain/models/query';
import { inject } from 'inversify';
import { GetWeatherQuery } from './get_weather_query';

export class GetWeatherHandler {
  private readonly _weatherRepository: IWeatherRepository;

  constructor(
    @inject(TYPES.IWeatherRepository) weatherRepository: IWeatherRepository,
  ) {
    this._weatherRepository = weatherRepository;
  }

  handle(query: Query<GetWeatherQuery>) {
    return this._weatherRepository.getWeather(query);
  }
}
