import { createAsyncThunk } from "@reduxjs/toolkit";
import { GetAddressHandler } from "@src/application/address/get_address_handle";
import { GetDistrictPayload } from "@src/application/address/get_district_payload";
import { GetProvincePayload } from "@src/application/address/get_province_payload";
import { GetWardPayload } from "@src/application/address/get_ward_payload";
import { container } from "@src/di/inversify.config";
import { TYPES } from "@src/di/types/types";
import { Query } from "@src/domain/models/query";
import uuid from 'react-native-uuid';
export const getProvinceListThunk = createAsyncThunk(
    '/v1/address-provinces',
    async (requestPayload: GetProvincePayload['data']) => {

        console.log('\x1b[31m getProvinceListThunk', { requestPayload });
        const getProvinceListHandler =
            container.get<GetAddressHandler>(
                TYPES.GetAddressHandler,
            );
        // const data = new HdBody({
        //     data: { clientNo: requestPayload.clientNo },
        // }, 'SDKSERVICE-ADDRESS-GET-STATES', 'b04830b4-c928-4247-abb8-abada1f7ad76');
        // console.log('BINHPV3');
        // return await getProvinceListByClientNumberHandler.handle(data);

        const query = new Query<GetProvincePayload>({
            query: {
                requestId: uuid.v4(),
                channel: "Mobile",
                ipRequest: "128.0.0.1",
                language: "vn",
                deviceInfo: {
                    deviceId: "123-1232-123",
                    deviceName: "Testing",
                    os: "IOS",
                    osVersion: "15"
                },
                data: requestPayload,
            },
        });
        return await getProvinceListHandler.handle_get_province(query)
    },
);

