import { ActionButton, BottomSheetManager, createStyles, GradientButton, LinearProgressBar, LoadingBlockerView, SimpleHeader, Spacer, Theme, useTheme } from '@core/ui';
import React, { ReactNode, useEffect, useState } from 'react';
import { Alert, BackHandler, Image, ImageBackground, SafeAreaView, ScrollView, TouchableOpacity, View } from 'react-native';
import { Text, CheckBox } from '@core/ui';
import useCSS from '@src/presentation/style';
import { SectionField, sectionFieldProps } from './components/sectionField';
import { useSelector } from 'react-redux';
import { selectBranchSelected, selectClientInfo, selectCmsLoanRegisterConfig, selectCmsLoanRegisterTnC, selectCmsStaticData, selectCmsStaticLoanCollateral, selectCmsStaticLoanGender, selectCmsStaticLoanMethod, selectCmsStaticLoanPurpose, selectErrorMessage, selectFlowRegister, selectLoanDemandData, selectLoanDemandResponse, selectStatus } from './redux/selector';
import { useDispatch } from '@src/lib/redux';
import { confirmLoanRegister, fetchClientInfo, fetchCmsLoanRegisterConfig, fetchCmsLoanRegisterTnC, fetchCmsRegisterStaticData } from './redux/thunk';
