import getImg from '@src/utils/getImg';
import { selectUserInfo } from '@src/presentation/loan_products/selector';
import BottomSheetAddress from '@src/presentation/components/bottomSheetAddress/bottomSheetAddress';
import { getProvinceListThunk } from '@src/presentation/components/bottomSheetAddress/redux/thunk';
import { District } from '@src/domain/entities/address/district';
import { Province } from '@src/domain/entities/address/province';
import { Ward } from '@src/domain/entities/address/ward';
import BottomSheetInputCurrency from '@src/presentation/components/bottomSheetInputCurrency';

interface ListOptionProps {
    id: number;
    content: string;
    type: string;
    code: string;
    selected?: boolean;
}
